import{z as i,x as B,o as r,c as d,q as l,j as o,D as e,d as t,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"堆 UAF","description":"","frontmatter":{"title":"堆 UAF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-uaf.md","filePath":"cs/heap-uaf.md","lastUpdated":1791063341000}'),p={name:"cs/heap-uaf.md"};function c(h,a,f,m,u,D){const A=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="堆-uaf" tabindex="-1">堆 UAF <a class="header-anchor" href="#堆-uaf" aria-label="Permalink to &quot;堆 UAF&quot;">​</a></h1><div class="epigraph"><p>释放后指针仍被解引用，对象槽可能已租给别人。读则泄，写则改别人的对象——包括函数指针。生命周期错误与越界写是两条路，都能到达同一类控制数据。</p><footer>—— 据 Szekeres et al., SoK: Eternal War in Memory, Oakland 2013；对照 CWE-416</footer></div><p>上一课<a href="/cs/jop-cop">JOP</a>要函数指针可写。缺口是<strong>堆生命周期</strong>：UAF。本课讲悬挂指针与分配器复用，不给利用堆布局的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>free</code> 后未置空，后续使用碰到新对象。类型若不同，就是混淆的入口。缺口是所有权，不是再讲栈帧。语言与 GC、或 borrow checker，从根上删这类。</p><p><span class="marginnote">术语翻译：悬挂指针就是「钥匙还在手里、房间已退租」的状态——free 只还内存，不销毁指针变量，地址数值照旧。之后谁入住你不知道：读一下是串门，写一笔就是改了别人家的东西。</span></p><h3 id="双重释放" tabindex="-1">双重释放 <a class="header-anchor" href="#双重释放" aria-label="Permalink to &quot;双重释放&quot;">​</a></h3><p>重复 <code>free</code> 破坏分配器元数据，下一课专门收。UAF 是「用」；double-free 是「还两次」。</p><p><span class="marginnote">Szekeres SoK。ASan 后课检测。本课禁止构造 UAF 利用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：分配→释放→槽复用→悬挂指针。防御：置空、隔离释放、延迟复用、内存安全语言。对照 canary：帮不上堆对象内部。</p><p><span class="marginnote">直觉类比：「延迟复用/隔离释放」像酒店把退房房间晾一晚再出租——刚退租就复制的旧钥匙，开不进新客人的门。代价是内存占用升高：晾着的房间不能立刻接客，峰值「入住率」变低。</span></p>',13)),(r(),o(n,null,{default:e(()=>[s(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALLOC%5B%22%E5%88%86%E9%85%8D%22%5D%20--%3E%20FREE%5B%22%E9%87%8A%E6%94%BE%22%5D%0A%20%20FREE%20--%3E%20REUSE%5B%22%E6%A7%BD%E5%A4%8D%E7%94%A8%22%5D%0A%20%20DANG%5B%22%E6%82%AC%E6%8C%82%E6%8C%87%E9%92%88%22%5D%20--%3E%20REUSE%0A%20%20DANG%20--%3E%20BUG%5B%22%E8%AF%BB%E6%B3%84%E6%88%96%E5%86%99%E4%B8%B2%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"堆把时间轴引进空间安全。下一课分配器自身的元数据：chunk 头被改时，分配器成为原语。",-1)),a[5]||(a[5]=E("p",null,"各层防御分别切断链条的哪一环：",-1)),(r(),o(n,null,{default:e(()=>[s(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22free(p)%22%5D%20--%3E%20Q1%7B%22free%20%E5%90%8E%E7%BD%AE%E7%A9%BA%20p%3F%22%7D%0A%20%20Q1%20--%20%22%E6%98%AF%22%20--%3E%20S1%5B%22%E5%90%8E%E7%BB%AD%E8%AE%BF%E9%97%AE%E5%B4%A9%E5%9C%A8%E7%A9%BA%E6%8C%87%E9%92%88%2C%20%E5%BD%93%E5%9C%BA%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20Q1%20--%20%22%E5%90%A6%22%20--%3E%20Q2%7B%22%E6%A7%BD%E5%B7%B2%E7%A7%9F%E7%BB%99%E6%96%B0%E5%AF%B9%E8%B1%A1%3F%22%7D%0A%20%20Q2%20--%20%22%E6%98%AF%22%20--%3E%20UAF%5B%22%E6%97%A7%E6%8C%87%E9%92%88%E8%AF%BB%E5%86%99%E5%88%AB%E4%BA%BA%E7%9A%84%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20Q2%20--%20%22%E5%BB%B6%E8%BF%9F%E5%A4%8D%E7%94%A8%E9%9A%94%E7%A6%BB%E4%B8%AD%22%20--%3E%20S2%5B%22%E6%82%AC%E7%A9%BA%E7%AA%97%E5%8F%A3%E6%94%B6%E7%AA%84%2C%20%E5%8D%B1%E5%AE%B3%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">为什么重要：canary 这类守卫对 UAF 无能为力——它守「越界」，UAF 却是「合法地址、错误时间」。堆对象里若住了函数指针或 vtable 指针，一次错时的写就能改控制流，这正是 UAF 单列为 CWE-416 的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无堆风水。分配器攻击下一课仍只讲机制与加固。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制数据也可住在堆对象里。</li><li>UAF：释放后用，槽可能已是别人。</li><li>所有权与安全语言是根治；检测器后课。</li><li>下一课分配器元数据。</li><li>出处：Szekeres et al., Oakland 2013；CWE-416。</li></ul>',5))])}const C=i(p,[["render",c]]);export{_ as __pageData,C as default};
